"""Lightweight subprocess runner for Python generated by a local LLM.

This follows nanochat's execution API shape: return a structured result, run in
a fresh interpreter and temporary directory, capture output, and enforce a
timeout. It is not a security sandbox; do not run untrusted code without
review or stronger OS-level isolation.
"""

import os
import subprocess
import sys
import tempfile
from dataclasses import dataclass
from typing import Optional


@dataclass
class ExecutionResult:
    success: bool
    stdout: str
    stderr: str
    error: Optional[str] = None
    timeout: bool = False
    memory_exceeded: bool = False


GUARD = r"""
import builtins, os, shutil, subprocess, sys
for name in ("exit", "quit", "help"):
    setattr(builtins, name, None)
for name in ("kill", "system", "putenv", "remove", "removedirs", "rmdir",
             "chdir", "fork", "forkpty", "killpg", "rename", "renames",
             "truncate", "replace", "unlink", "chmod", "chown", "chroot"):
    if hasattr(os, name):
        setattr(os, name, None)
for name in ("rmtree", "move", "chown"):
    if hasattr(shutil, name):
        setattr(shutil, name, None)
subprocess.Popen = None
if sys.platform != "win32":
    import resource
    limit = {maximum_memory_bytes}
    for key in (resource.RLIMIT_AS, resource.RLIMIT_DATA, resource.RLIMIT_STACK):
        try:
            resource.setrlimit(key, (limit, limit))
        except (ValueError, OSError):
            pass
"""


def execute_code(
    code: str,
    timeout: float = 5.0,
    maximum_memory_bytes: Optional[int] = 256 * 1024 * 1024,
) -> ExecutionResult:
    """Execute Python in a short-lived subprocess and temporary working dir."""
    if not code.strip():
        return ExecutionResult(False, "", "", error="No Python code was provided.")

    memory_limit = "None" if maximum_memory_bytes is None else str(maximum_memory_bytes)
    guard = GUARD.format(maximum_memory_bytes=memory_limit)
    program = guard + f"\nexec(compile({code!r}, '<model>', 'exec'), {{'__name__': '__main__'}})\n"
    env = {"PATH": os.defpath}
    # Windows needs these variables to start Python and load its runtime.
    for key in ("SYSTEMROOT", "WINDIR", "TEMP", "TMP", "LANG", "LC_ALL"):
        value = os.environ.get(key)
        if value:
            env[key] = value

    try:
        with tempfile.TemporaryDirectory(prefix="minimind-code-") as workdir:
            process = subprocess.run(
                [sys.executable, "-I", "-c", program],
                cwd=workdir,
                env=env,
                stdin=subprocess.DEVNULL,
                capture_output=True,
                text=True,
                timeout=timeout,
                check=False,
            )
    except subprocess.TimeoutExpired:
        return ExecutionResult(False, "", "", error=f"Execution timed out after {timeout:g} seconds.", timeout=True)
    except OSError as exc:
        return ExecutionResult(False, "", "", error=f"Could not start Python: {exc}")

    stdout = process.stdout[-12000:]
    stderr = process.stderr[-4000:]
    success = process.returncode == 0
    error = None if success else (stderr.strip().splitlines()[-1] if stderr.strip() else f"Python exited with status {process.returncode}.")
    return ExecutionResult(success, stdout, stderr, error, memory_exceeded="MemoryError" in stderr)
